/**
 * Resolve the logged-in farmer id, verified against the session cookie.
 * Redirects to the login page and resolves to null when there is no session.
 *
 * On a network failure we trust the cached id rather than logging the farmer
 * out — dropping someone on flaky 4G is worse than letting them read a page
 * whose writes would 401 anyway (and `farmerFetch` catches that).
 */
export async function requireFarmerSession(): Promise<string | null> {
  const cachedId = localStorage.getItem(ID_KEY)
  if (!cachedId) {
    goToFarmerLogin('required')
    return null
  }

  let res: Response
  try {
    res = await fetch('/api/auth/me', { credentials: 'same-origin', cache: 'no-store' })
  } catch {
    return cachedId
  }
  if (!res.ok) return cachedId

  const farmer = (await res.json().catch(() => ({}))).farmer as
    | { id: string; slug?: string | null }
    | null
    | undefined

  if (!farmer?.id) {
    goToFarmerLogin('expired')
    return null
  }

  // Cookie wins over the cache if they ever disagree (e.g. two farmers sharing
  // a phone, or a stale id left by an old build).
  if (farmer.id !== cachedId) {
    localStorage.setItem(ID_KEY, farmer.id)
    if (farmer.slug) localStorage.setItem(SLUG_KEY, farmer.slug)
  }
  return farmer.id
}

