'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'

// Shared add/edit form for a farmer's harvest listing, used by both
//   /moderator/listings/new          (mode="create")
//   /moderator/listings/[id]/edit    (mode="edit")
// Create posts to /api/moderator/listings; edit PUTs to that listing's [id].
//
// Kept at full parity with the FARMER's Edit Harvest form (moderators register
// farmers and add/edit harvests on their behalf, so they get every field the
// farmer has): icon, name, variety, method, category, unit, stock, brix,
// harvest date/time, shelf life, delivery method (pickup/courier/both + charge
// & radius), three price tiers, photos, soil quality (organic carbon, pH),
// pesticide result, and description.

export type ListingFormValues = {
  name: string
  variety: string
  method: string
  category: string
  unit: string
  stock_qty: string
  description: string
  brix: string
  harvest_date: string
  shelf_life_days: string
  price_tier_1_qty: string
  price_tier_1_price: string
  price_tier_2_qty: string
  price_tier_2_price: string
  price_tier_3_price: string
  soil_organic_carbon: string
  soil_ph: string
  pesticide_result: string
  availability_from: string
  availability_to: string
  harvest_frequency: string
  harvest_frequency_count: string
  // How this produce is fulfilled: pickup only, farmer courier, or both. Mirrors
  // the farmer form's Delivery method — the cart uses it to constrain each line's
  // pickup/delivery choice, so it must be settable here too.
  delivery_mode: string
  delivery_charge: string
  delivery_radius_km: string
}

export const EMPTY_LISTING_FORM: ListingFormValues = {
  name: '', variety: '', method: 'natural', category: '', unit: 'kg',
  stock_qty: '', description: '', brix: '', harvest_date: '', shelf_life_days: '',
  price_tier_1_qty: '1', price_tier_1_price: '',
  price_tier_2_qty: '', price_tier_2_price: '',
  price_tier_3_price: '',
  soil_organic_carbon: '', soil_ph: '', pesticide_result: '',
  availability_from: '', availability_to: '',
  harvest_frequency: '', harvest_frequency_count: '',
  delivery_mode: 'pickup', delivery_charge: '', delivery_radius_km: '',
}

const DELIVERY_MODES = [
  { key: 'pickup', label: 'Pickup only', icon: '🧺' },
  { key: 'courier', label: 'Farmer courier', icon: '🛵' },
  { key: 'both', label: 'Both', icon: '🔁' },
] as const

const EMOJIS = ['📦', '🍅', '🥬', '🥕', '🧅', '🥔', '🍆', '🌶️', '🥭', '🍌', '🍋', '🥥', '🌽', '🫛']
const UNITS = ['kg', 'g', 'litre', 'dozen', 'piece', 'bunch']
// Mirrors the farmer form's category options (drives the consumer category filter).
const CATEGORIES = [
  { v: 'vegetables', label: 'Vegetables' },
  { v: 'fruits', label: 'Fruits' },
  { v: 'grains', label: 'Grains & Pulses' },
  { v: 'leafy', label: 'Leafy Greens' },
  { v: 'spices', label: 'Spices' },
  { v: 'other', label: 'Other' },
]

type FarmerOption = { id: string; name: string; village: string | null }

export default function ListingForm({
  mode,
  zone,
  listingId,
  initialForm = EMPTY_LISTING_FORM,
  initialEmoji = '📦',
  initialFarmerId = '',
  initialImages = [],
  fixedFarmerName,
}: {
  mode: 'create' | 'edit'
  zone: string
  listingId?: string
  initialForm?: ListingFormValues
  initialEmoji?: string
  initialFarmerId?: string
  initialImages?: string[]
  fixedFarmerName?: string
}) {
  const router = useRouter()

content.content:
// (Harvest date/time is now per-pick in the harvests model, not on the
// produce, so it's no longer required here.)
const shelfNum = parseInt(shelfLifeDays, 10)
if (!shelfLifeDays || !Number.isFinite(shelfNum) || shelfNum <= 0) {
  setError(L('Shelf life (days) is required.', 'తాజా (రోజులు) తప్పనిసరి.'))
  return
}
setLoading(true)
setError('')

let imageUrl: string | null = null
if (imageFile) {
  imageUrl = await uploadImage(imageFile)
  if (!imageUrl) { setLoading(false); return }
} else if (existingImageUrl) {
  imageUrl = existingImageUrl
}

// #12 — upload any new extra photos, then assemble the full ordered set
// (cover first). Best-effort: persisted via the secondary update below.
const uploadedExtra: string[] = []
for (const f of extraFiles) {
  const u = await uploadImage(f)
  if (u) uploadedExtra.push(u)
}
const allImages = [imageUrl, ...existingExtraUrls, ...uploadedExtra].filter(Boolean) as string[]

// Harvest date+time (datetime-local, local time) → stored UTC ISO string.
// Shelf life is an optional non-negative day count.
const harvestDateIso = harvestDate ? new Date(harvestDate).toISOString() : null
const shelfLifeVal = shelfLifeDays ? Math.max(0, parseInt(shelfLifeDays, 10)) : null

if (isEdit && editData) {
  // Edit mode: always send all fields so clearing a value actually clears it in DB
  const editPayload: Record<string, unknown> = {
    name: name.trim(),
    emoji,
    method: farmingMethod,
    unit,
    variety: variety.trim() || null,
    stock_qty: qty ? Number(qty) : null,
    description: description.trim() || null,
    brix: brix ? Number(brix) : null,
    soil_organic_carbon: soc ? Number(soc) : null,
    price_tier_1_price: price1 ? Number(price1) : null,
    price_tier_1_qty: price1 ? Number(price1Qty) : null,
    price_tier_2_price: price2 ? Number(price2) : null,
    price_tier_2_qty: price2 ? Number(price2Qty) : null,
    price_tier_3_price: price3 ? Number(price3) : null,
    price_tier_3_qty: price3 ? Number(Number(price2Qty) + 1) : null,
    image_url: imageUrl,
    availability_from: availFrom || null,
    availability_to: availTo || null,
    harvest_frequency: harvestFreq || null,
    harvest_frequency_count: harvestFreqCount ? Number(harvestFreqCount) : null,
    harvest_date: harvestDateIso,
    shelf_life_days: shelfLifeVal,
    delivery_mode: deliveryMode,
    delivery_charge: deliveryMode === 'pickup' ? null : (deliveryCharge ? Number(deliveryCharge) : null),
    delivery_radius_km: deliveryMode === 'pickup' ? null : (deliveryRadius ? Number(deliveryRadius) : null),
  }

  let res: Response
  try {
    res = await farmerFetch('/api/farmer/update-listing', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ listingId: editData.id, payload: editPayload }),
