const [farmers, setFarmers] = useState<FarmerOption[]>([])
const [loadingFarmers, setLoadingFarmers] = useState(mode === 'create')

const [farmerId, setFarmerId] = useState(initialFarmerId)
const [emoji, setEmoji] = useState(initialEmoji)
const [form, setForm] = useState<ListingFormValues>(initialForm)
// Photos: already-saved image URLs + files newly picked this session (with
// object-URL previews). Uploaded to Supabase storage on submit.
const [existingImages, setExistingImages] = useState<string[]>(initialImages)
const [newFiles, setNewFiles] = useState<File[]>([])
const [newPreviews, setNewPreviews] = useState<string[]>([])
const [error, setError] = useState('')
const [submitting, setSubmitting] = useState(false)
const [done, setDone] = useState(false)

const set = (k: keyof ListingFormValues) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
  setForm((f) => ({ ...f, [k]: e.target.value }))

// Revoke object URLs on unmount so previews don't leak memory.
useEffect(() => () => { newPreviews.forEach((u) => URL.revokeObjectURL(u)) }, [newPreviews])

// Farmer list is only needed when creating (edit keeps the listing's farmer).
useEffect(() => {
  if (mode !== 'create') return
  fetch('/api/moderator/farmers', { credentials: 'same-origin' })
    .then((r) => r.json())
    .then((j) => setFarmers((j.farmers ?? []).map((f: { id: string; name: string; village: string | null }) => ({ id: f.id, name: f.name, village: f.village }))))
    .catch(() => setError('Could not load farmers.'))
    .finally(() => setLoadingFarmers(false))
}, [mode])

const onAddFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
  const files = Array.from(e.target.files ?? [])
  if (files.length) {
    setNewFiles((prev) => [...prev, ...files])
    setNewPreviews((prev) => [...prev, ...files.map((f) => URL.createObjectURL(f))])
  }
  e.target.value = ''
}
const removeExisting = (i: number) => setExistingImages((prev) => prev.filter((_, x) => x !== i))
const removeNew = (i: number) => {
  setNewPreviews((prev) => { URL.revokeObjectURL(prev[i]); return prev.filter((_, x) => x !== i) })
  setNewFiles((prev) => prev.filter((_, x) => x !== i))
}

// Upload one image to the shared farm-images bucket (same bucket + anon-write
// policy the farmer dashboard uses). Foldered by farmer so paths stay tidy.
const uploadImage = async (file: File): Promise<string | null> => {
  const ext = file.name.split('.').pop()?.toLowerCase() || 'jpg'
  const path = `${farmerId || 'moderator'}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`
  const { error: upErr } = await supabase.storage
    .from('farm-images')
    .upload(path, file, { contentType: file.type, upsert: false })
  if (upErr) { setError(`Image upload failed: ${upErr.message}`); return null }
  const { data } = supabase.storage.from('farm-images').getPublicUrl(path)
  return data.publicUrl
}

const submit = async (e: React.FormEvent) => {
  e.preventDefault()
  if (submitting) return
  if (mode === 'create' && !farmerId) { setError('Choose a farmer.'); return }
  if (!form.name.trim()) { setError('Harvest name is required.'); return }
  // The moderator form has no separate harvest logger (unlike the farmer's
  // HarvestManager), so this "Harvest date & time" field IS how a moderator
  // seeds/updates the produce's harvest row — hence still required here, while
  // the farmer's produce form drops it in favour of per-pick logging.
  if (!form.harvest_date) { setError('Harvest date & time is required.'); return }
  const shelfNum = parseInt(form.shelf_life_days, 10)
  if (!form.shelf_life_days || !Number.isFinite(shelfNum) || shelfNum <= 0) {
    setError('Shelf life (days) is required.'); return
  }
  setError(''); setSubmitting(true)

  // Upload any newly-picked photos first; abort on failure (error is set by
  // uploadImage). The first image becomes the card cover (image_url).
  const uploaded: string[] = []
  for (const f of newFiles) {
    const u = await uploadImage(f)
    if (!u) { setSubmitting(false); return }
    uploaded.push(u)
  }
  const allImages = [...existingImages, ...uploaded]

  const url = mode === 'edit' ? `/api/moderator/listings/${listingId}` : '/api/moderator/listings'
  const method = mode === 'edit' ? 'PUT' : 'POST'
  const r = await fetch(url, {
    method,
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({
      ...form,
      farmer_id: farmerId,
      emoji,
      image_url: allImages[0] ?? null,
    }),
  }).catch(() => null)
  if (!r) { setSubmitting(false); setError('Network error.'); return }
  const json = await r.json().catch(() => ({}))
  if (!r.ok) { setSubmitting(false); setError(json?.error ?? (mode === 'edit' ? 'Could not save changes.' : 'Could not add harvest.')); return }

  // Quality fields (category, soil pH, pesticide result, photo gallery) are a
  // best-effort direct write — their columns may not exist until the quality
  // migration is applied, so they must never block the core save. Mirrors the
  // farmer dashboard's qualityPatch exactly.
  const savedId = mode === 'edit' ? listingId : (json?.id as string | undefined)
  if (savedId) {
    await supabase.from('produce_listings').update({
      category: form.category || null,
      soil_ph: form.soil_ph ? Number(form.soil_ph) : null,
      pesticide_result: form.pesticide_result.trim() || null,
      image_urls: allImages.length ? allImages : null,
    }).eq('id', savedId)
  }

  setSubmitting(false)
  if (mode === 'edit') { router.push('/moderator/listings'); return }
  setDone(true)
}

if (done) {
  const farmer = farmers.find((f) => f.id === farmerId)
  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-6 max-w-md">
      <div className="text-4xl mb-2">✅</div>
      <h2 className="text-lg font-extrabold text-gray-900">{form.name} is live</h2>
      <p className="text-sm text-gray-500 mt-1">Added for {farmer?.name ?? 'the farmer'} and visible to buyers now.</p>
      <div className="flex flex-col gap-2 mt-5">
        <button

content.content:
              onPublished={() => {
                setShowAddForm(false)
                load()
                onChanged()
              }}
            />
          </div>
        </div>
      )}
    </div>
  )
}

/* ─── Harvest timings manager (lives inside the produce Edit form) ─────
   A produce_listing is the template; logging a harvest records one actual pick
   (date+time, shelf life, qty-for-sale) into the `harvests` table — each pick is
   its own sellable product powering the consumer "Today's Harvest" feed and the
   "Harvested 2h ago" clock. This whole panel used to be a separate button on the
   produce card; it now lives inside Edit. */
function HarvestManager({ listingId, farmerId, unit, produceShelfLife }: { listingId: string; farmerId: string; unit?: string | null; produceShelfLife?: number | null }) {
  const { L } = useLang()
  const nowLocal = () => {
    const d = new Date()
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
    return d.toISOString().slice(0, 16) // yyyy-MM-ddThh:mm for datetime-local
  }
  // datetime-local wants yyyy-MM-ddThh:mm in LOCAL time; convert a stored UTC
  // ISO string back to that shape for the edit inputs.
  const toLocalInput = (iso: string) => {
    const d = new Date(iso)
    if (isNaN(d.getTime())) return ''
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
    return d.toISOString().slice(0, 16)
  }
  const [harvestedAt, setHarvestedAt] = useState(nowLocal())
  const [approxQty, setApproxQty] = useState('')
  const [savingHarvest, setSavingHarvest] = useState(false)
  const [harvestMsg, setHarvestMsg] = useState('')
  const [harvestErr, setHarvestErr] = useState('')

  const [harvests, setHarvests] = useState<Harvest[]>([])
  const [harvestsLoaded, setHarvestsLoaded] = useState(false)
  const [editingHarvestId, setEditingHarvestId] = useState<string | null>(null)
  const [editAt, setEditAt] = useState('')
  const [editQty, setEditQty] = useState('')
  const [savingEdit, setSavingEdit] = useState(false)
  const [editErr, setEditErr] = useState('')

  const loadHarvests = useCallback(async () => {
    const { data } = await supabase
      .from('harvests')
      .select('id, produce_listing_id, farmer_id, harvested_at, shelf_life_days, approx_quantity, unit, notes')
      .eq('produce_listing_id', listingId)
      .order('harvested_at', { ascending: false })
      .limit(20)
    setHarvests((data ?? []) as Harvest[])
    setHarvestsLoaded(true)
  }, [listingId])

  useEffect(() => { void loadHarvests() }, [loadHarvests])

  const submitHarvest = async () => {
    setHarvestErr('')
    setHarvestMsg('')
    const when = new Date(harvestedAt)
    if (isNaN(when.getTime())) { setHarvestErr(L('Pick a valid harvest date & time.', 'సరైన కోత తేదీ & సమయం ఎంచుకోండి.')); return }
    setSavingHarvest(true)
    // Shelf life is not logged per-harvest — it's a produce-level property, so
    // the consumer freshness label falls back to the listing's shelf_life_days.
    const { error: err } = await supabase.from('harvests').insert({
      produce_listing_id: listingId,
      farmer_id: farmerId,
      harvested_at: when.toISOString(),
      approx_quantity: approxQty ? Number(approxQty) : null,
      // The quantity entered is this harvest's sellable stock: each harvest is
      // its own product with its own inventory (decremented as buyers order).
      stock_qty: approxQty ? Number(approxQty) : null,
      unit: unit ?? null,
    })
    setSavingHarvest(false)
    if (err) { setHarvestErr(err.message); return }
    setHarvestMsg(L('Harvest logged ✓', 'కోత నమోదైంది ✓'))
    setApproxQty(''); setHarvestedAt(nowLocal())
    void loadHarvests()
    setTimeout(() => setHarvestMsg(''), 1400)
  }

  const startEditHarvest = (h: Harvest) => {
    setEditingHarvestId(h.id)
    setEditErr('')
    setEditAt(toLocalInput(h.harvested_at))
    setEditQty(h.approx_quantity != null ? String(h.approx_quantity) : '')
  }

  const saveEditHarvest = async () => {
    if (!editingHarvestId) return
    setEditErr('')
    const when = new Date(editAt)
    if (isNaN(when.getTime())) { setEditErr(L('Pick a valid harvest date & time.', 'సరైన కోత తేదీ & సమయం ఎంచుకోండి.')); return }
    setSavingEdit(true)
    const { error: err } = await supabase.from('harvests').update({
      harvested_at: when.toISOString(),
      approx_quantity: editQty ? Number(editQty) : null,
      // Editing the quantity resets this harvest's sellable stock to the new
      // amount (the farmer is stating what's actually available now).
      stock_qty: editQty ? Number(editQty) : null,
    }).eq('id', editingHarvestId)
    setSavingEdit(false)
    if (err) { setEditErr(err.message); return }
    setEditingHarvestId(null)
    void loadHarvests()
  }

  const deleteHarvest = async (h: Harvest) => {
    if (!window.confirm(L('Delete this harvest? This cannot be undone.', 'ఈ కోతను తొలగించాలా? దీన్ని తిరిగి మార్చలేరు.'))) return
    const { error: err } = await supabase.from('harvests').delete().eq('id', h.id)
    if (err) { setHarvestErr(err.message); return }
    if (editingHarvestId === h.id) setEditingHarvestId(null)
    void loadHarvests()
  }

  return (
    <div className="bg-green-50 border border-green-200 rounded-xl p-3 space-y-2.5">
      <p className="text-xs font-bold text-green-800">🌾 {L('Harvest timings', 'కోత సమయాలు')}</p>
      <div>
        <label className="text-[11px] font-semibold text-gray-600">{L('Harvest date & time', 'కోత తేదీ & సమయం')}</label>
        <input
          type="datetime-local"
          value={harvestedAt}
          onChange={(e) => setHarvestedAt(e.target.value)}
          className="mt-1 w-full border border-gray-300 rounded-lg px-2.5 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
        />
      </div>
      <div>
        <label className="text-[11px] font-semibold text-gray-600">{L('Qty for sale', 'అమ్మకానికి పరిమాణం')} ({unit || 'kg'})</label>
        <input
          type="number" inputMode="decimal" min={0} placeholder="e.g. 20"
          value={approxQty}
          onChange={(e) => setApproxQty(e.target.value)}
          className="mt-1 w-full border border-gray-300 rounded-lg px-2.5 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
        />

toolUseResult.stdout:
              onPublished={() => {
                setShowAddForm(false)
                load()
                onChanged()
              }}
            />
          </div>
        </div>
      )}
    </div>
  )
}

